float4 readInput(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);return float4(image.eval(uv * size));}
half4 main(float2 coord){float2 p=((toLayer * float3(coord,1.0)).xy / layer)-float2(.5);float a=atan(p.y,p.x)+angle*.0174532925,sector=6.2831853/max(2.0,floor(segments));a=abs(mod(a+sector*.5,sector)-sector*.5);float2 uv=float2(cos(a),sin(a))*length(p)+float2(.5);return readInput(((fromLayer * float3(uv * layer,1.0)).xy / size));}
